  ja: { "Good morning": "\u304A\u306F\u3088\u3046\u3054\u3056\u3044\u307E\u3059", "Good afternoon": "\u3053\u3093\u306B\u3061\u306F", "Good evening": "\u3053\u3093\u3070\u3093\u306F", "Good night": "\u304A\u3084\u3059\u307F\u306A\u3055\u3044", "A gentle note to pause and sip. Choose a small habit goal if it feels helpful.": "\u3072\u3068\u4F11\u307F\u3057\u3066\u6C34\u3092\u98F2\u307F\u307E\u3057\u3087\u3046\u3002\u3088\u3051\u308C\u3070\u5C0F\u3055\u306A\u7FD2\u6163\u306E\u76EE\u6A19\u3092\u9078\u3079\u307E\u3059\u3002", "My gentle daily goal": "\u4ECA\u65E5\u306E\u5C0F\u3055\u306A\u76EE\u6A19", "Choose a gentle goal to see your progress, or leave it off.": "\u76EE\u6A19\u3092\u9078\u3076\u3068\u9032\u307F\u5177\u5408\u304C\u8868\u793A\u3055\u308C\u307E\u3059\u3002\u8A2D\u5B9A\u3057\u306A\u304F\u3066\u3082\u5927\u4E08\u592B\u3067\u3059\u3002", "A small reminder, never a rule. Drink when you feel thirsty.": "\u3053\u308C\u306F\u5C0F\u3055\u306A\u304A\u77E5\u3089\u305B\u3067\u3059\u3002\u306E\u3069\u304C\u6E07\u3044\u305F\u3089\u6C34\u3092\u98F2\u307F\u307E\u3057\u3087\u3046\u3002", "You reached the goal you chose. Take a comfortable pause.": "\u81EA\u5206\u3067\u6C7A\u3081\u305F\u76EE\u6A19\u306B\u5C4A\u304D\u307E\u3057\u305F\u3002\u3086\u3063\u304F\u308A\u3072\u3068\u4F11\u307F\u3057\u307E\u3057\u3087\u3046\u3002", "Goal reached \xB7 nice work!": "\u76EE\u6A19\u9054\u6210\u30FB\u3059\u3070\u3089\u3057\u3044\u3067\u3059\uFF01", "No goal": "\u76EE\u6A19\u306A\u3057", "cups": "\u676F", "Quote language": "\u5F15\u7528\u306E\u8A00\u8A9E", "Quote topic": "\u5F15\u7528\u306E\u30C6\u30FC\u30DE", "App language": "\u30A2\u30D7\u30EA\u306E\u8A00\u8A9E" }
